.create-controls { display: flex; gap: 12px; }
input, button { font: inherit; border-radius: 8px; padding: 11px 16px; }
input { min-width: 0; flex: 1; border: 1px solid #83999d; background: white; }
button { cursor: pointer; border: 1px solid #17665c; background: #17665c; color: white; font-weight: 600; }
button:hover { background: #104c44; }
button:disabled { cursor: default; opacity: .55; }
.secondary { color: #17665c; background: white; }
.secondary:hover { background: #e9f3f0; }
:focus-visible { outline: 3px solid #bf7014; outline-offset: 3px; }
.project-list { border: 1px solid #cad7d6; background: white; border-radius: 12px; overflow: hidden; }
.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px; padding: 20px; }
.project-row + .project-row { border-top: 1px solid #dde5e3; }
.project-name { font-weight: 600; overflow-wrap: anywhere; min-width: 0; }
.project-row form { flex-shrink: 0; }
.empty { color: #526d72; }
.alert { color: #942d25; background: #fff0ee; border: 1px solid #e7b5af; padding: 12px 16px; border-radius: 8px; }
.filter-form { margin-bottom: 20px; }
select { font: inherit; padding: 10px 16px; border: 1px solid #83999d; border-radius: 8px; background: white; }
.task-list { border: 1px solid #cad7d6; background: white; border-radius: 12px; overflow: hidden; }
.task-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px; padding: 20px; }
.task-row + .task-row { border-top: 1px solid #dde5e3; }
.task-title { overflow-wrap: anywhere; min-width: 0; }
.task-rename-form { flex-basis: 100%; }
.task-row input[type="checkbox"] { width: 22px; height: 22px; margin: 0; cursor: pointer; accent-color: #17665c; }
.task-row input[type="checkbox"]:disabled { cursor: default; }
@media (max-width: 540px) {
  main { margin-top: 32px; padding: 0 16px; }
  .create-controls { flex-direction: column; }
  .project-row { align-items: flex-start; flex-direction: column; gap: 12px; }
}

